sp_widget.client_script:
function($scope, $timeout) {
  $timeout(function() {
    if (typeof Chart !== 'undefined' && $scope.data.percent_despesa_2024 !== 'N/D') {
      var percent = parseFloat($scope.data.percent_despesa_2024);
      var limites = [
        parseFloat($scope.data.limite_alerta),
        parseFloat($scope.data.limite_prudencial),
        parseFloat($scope.data.limite_maximo)
      ];

      var ctx = document.getElementById('despesaChart').getContext('2d');
      new Chart(ctx, {
        type: 'bar',
        data: {
          labels: ['Comprometimento', 'Alerta', 'Prudencial', 'Máximo'],
          datasets: [{
            label: '% Despesa',
            data: [percent, ...limites],
            backgroundColor: [
              'rgba(59, 130, 246, 0.8)',  // azul
              'rgba(234, 179, 8, 0.6)',   // amarelo
              'rgba(249, 115, 22, 0.6)',  // laranja
              'rgba(220, 38, 38, 0.6)'    // vermelho
            ],
            borderRadius: 10
          }]
        },
        options: {
          plugins: {
            legend: { display: false },
            tooltip: { enabled: true }
          },
          scales: {
            y: {
              beginAtZero: true,
              max: 100,
              ticks: {
                callback: function(value) { return value + '%' }
              }
            }
          }
        }
      });
    }
  }, 500);
}

sp_widget.css:
.widget-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 30px;
  font-family: 'Segoe UI', sans-serif;
}

.info-container {
  width: 100%;
  text-align: center;
}

.chart-container {
  width: 100%;
  max-width: 600px;
}

sp_widget.script:
(function() {
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
  gr.addQuery('u_ano', 2024);
  gr.query();

  if (gr.next()) {
    data.percent_despesa_2024 = parseFloat(gr.u_comprometimento_rcl).toFixed(2);
    data.valor_despesa_2024 = (parseFloat(gr.u_despesa_liquida_pedidos) / 1000000).toFixed(2);
    data.limite_alerta = parseFloat(gr.u_limite_de_alerta).toFixed(2);
    data.limite_prudencial = parseFloat(gr.u_limite_prudencial).toFixed(2);
    data.limite_maximo = parseFloat(gr.u_limite_maximo).toFixed(2);
  } else {
    data.percent_despesa_2024 = 'N/D';
    data.valor_despesa_2024 = 'N/D';
    data.limite_alerta = 'N/D';
    data.limite_prudencial = 'N/D';
    data.limite_maximo = 'N/D';
  }
})();
